INSERT INTO examinations(patientId,visitId) SELECT h.patientId,f.visitId FROM followupItems f INNER JOIN followupSheets h ON h.id=f.followupSheetId INNER JOIN visits v ON v.id=f.visitId AND v.patientId=h.patientId LEFT JOIN examinations e ON e.visitId=v.id AND e.patientId=v.patientId WHERE e.id IS NULL GROUP BY h.patientId,f.visitId;
