UPDATE medicalTypedCandidates SET candidateValue=CASE WHEN candidateValue='true' THEN '1' WHEN candidateValue='false' THEN '0' ELSE candidateValue END WHERE targetName='examinationFindings' AND fieldName IN ('externalOthers','externalPtosis','externalSquint','fundusAbnormal','fundusNormal','glassesCheck','muscleAbnormal','muscleNormal','xrayCheck');
--> statement-breakpoint
