INSERT INTO medicalMigrationConflicts(patientId,visitId,fieldName,sourceRef,candidateValue) SELECT patientId,visitId,CONCAT('oversize:',targetName,':',fieldName),sourceRef,candidateValue FROM medicalTypedCandidates WHERE ((targetName IN ('glassesRecords','afterRefractionData','autorefractometryData','pentacamResults') AND CHAR_LENGTH(candidateValue)>20) OR (targetName='airPuffMeasurements' AND CHAR_LENGTH(candidateValue)>50) OR (targetName='examinationFindings' AND fieldName='readingValue' AND CHAR_LENGTH(candidateValue)>100)) ON DUPLICATE KEY UPDATE sourceRef=VALUES(sourceRef);
--> statement-breakpoint
DELETE FROM medicalTypedCandidates WHERE ((targetName IN ('glassesRecords','afterRefractionData','autorefractometryData','pentacamResults') AND CHAR_LENGTH(candidateValue)>20) OR (targetName='airPuffMeasurements' AND CHAR_LENGTH(candidateValue)>50) OR (targetName='examinationFindings' AND fieldName='readingValue' AND CHAR_LENGTH(candidateValue)>100));
--> statement-breakpoint
CREATE TEMPORARY TABLE medicalTypedSummary AS SELECT examinationId,targetName,fieldName,COUNT(DISTINCT CAST(candidateValue AS BINARY)) AS variants FROM medicalTypedCandidates GROUP BY examinationId,targetName,fieldName;
--> statement-breakpoint
INSERT INTO medicalMigrationConflicts(patientId,visitId,fieldName,sourceRef,candidateValue) SELECT c.patientId,c.visitId,CONCAT(c.targetName,':',c.examinationId,':',c.fieldName),c.sourceRef,c.candidateValue FROM medicalTypedCandidates c INNER JOIN medicalTypedSummary s ON s.examinationId=c.examinationId AND s.targetName=c.targetName AND s.fieldName=c.fieldName AND s.variants>1 ON DUPLICATE KEY UPDATE sourceRef=VALUES(sourceRef);
