INSERT INTO `glassesRecords`(`patientId`,`examinationId`,`sOD`,`cOD`,`axisOD`,`pdOD`,`addOD`,`bcvaOD`,`sOS`,`cOS`,`axisOS`,`pdOS`,`addOS`,`bcvaOS`) SELECT MIN(c.patientId),c.examinationId,MAX(CASE WHEN c.fieldName='sOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='cOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='axisOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='pdOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='addOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='bcvaOD' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='sOS' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='cOS' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='axisOS' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='pdOS' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='addOS' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='bcvaOS' AND s.variants=1 THEN c.candidateValue END) FROM medicalTypedCandidates c INNER JOIN medicalTypedSummary s ON s.examinationId=c.examinationId AND s.targetName=c.targetName AND s.fieldName=c.fieldName LEFT JOIN `glassesRecords` existingRow ON existingRow.examinationId=c.examinationId WHERE c.targetName='glassesRecords' AND existingRow.id IS NULL GROUP BY c.examinationId;
