INSERT INTO `examinationProcedurePlans`(`patientId`,`examinationId`,`visitId`,`eye`,`target`,`beforeFlap`,`afterFlap`,`afterTreatment`,`flapReposition`,`ciclo`,`note`) SELECT MIN(c.patientId),c.examinationId,MIN(c.visitId),'OD',MAX(CASE WHEN c.fieldName='target' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='beforeFlap' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='afterFlap' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='afterTreatment' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='flapReposition' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='ciclo' AND s.variants=1 THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='note' AND s.variants=1 THEN c.candidateValue END) FROM medicalTypedCandidates c INNER JOIN medicalTypedSummary s ON s.examinationId=c.examinationId AND s.targetName=c.targetName AND s.fieldName=c.fieldName LEFT JOIN `examinationProcedurePlans` existingRow ON existingRow.examinationId=c.examinationId AND existingRow.eye='OD' WHERE c.targetName='procedureOD' AND existingRow.id IS NULL GROUP BY c.examinationId;
