INSERT INTO examination_checklist_items(patientId,examinationId,generalDiseases,pregnancyOrLactation,usesAllergySupplementsSteroidsOrPressureMeds,acneTreatment,familyKeratoconus,usesTearSubstituteOrExcessTearsOrSandySensation,symptomsWorseWithAirOrAC,glaucomaTreatment) SELECT MIN(c.patientId),c.examinationId,MAX(CASE WHEN c.fieldName='generalDiseases' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='pregnancyOrLactation' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='usesAllergySupplementsSteroidsOrPressureMeds' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='acneTreatment' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='familyKeratoconus' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='usesTearSubstituteOrExcessTearsOrSandySensation' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='symptomsWorseWithAirOrAC' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END),MAX(CASE WHEN c.fieldName='glaucomaTreatment' AND r.variants=1 AND c.candidateValue IN ('0','1') THEN c.candidateValue END) FROM medicalTypedCandidates c INNER JOIN medicalTypedSummary r ON r.examinationId=c.examinationId AND r.targetName=c.targetName AND r.fieldName=c.fieldName LEFT JOIN examination_checklist_items t ON t.examinationId=c.examinationId WHERE c.targetName='examination_checklist_items' AND t.id IS NULL GROUP BY c.examinationId;
