INSERT INTO medicalMigrationConflicts(patientId,visitId,fieldName,sourceRef,candidateValue) SELECT p.patientId,NULL,'checklist:generalDiseases',CONCAT('cache-checklist:',p.id),JSON_UNQUOTE(JSON_EXTRACT(p.data,'$.medicalChecklist.generalDiseases')) FROM patientPageStates p WHERE p.page='examination' AND JSON_TYPE(JSON_EXTRACT(p.data,'$.medicalChecklist.generalDiseases')) IN ('BOOLEAN','INTEGER') AND NOT EXISTS(SELECT 1 FROM medicalTypedCandidates c WHERE c.targetName='examination_checklist_items' AND c.fieldName='generalDiseases' AND c.sourceRef=CONCAT('cache-checklist:',p.id)) AND NOT EXISTS(SELECT 1 FROM examination_checklist_items t WHERE t.patientId=p.patientId) ON DUPLICATE KEY UPDATE sourceRef=VALUES(sourceRef);
